#!/usr/bin/env node
/* ============================================================
   Regenerate goals/bundle.js from the JSON goal lists.

     node tools/build-bundle.js

   JSON is the source of truth. Served over http(s) the page fetches
   it directly and never touches the bundle. But fetch is blocked on
   file://, so this bakes the same data into a script tag for opening
   index.html straight off disk.

   Re-run it whenever you add or edit a list. If you only ever use a
   real server you can skip it, and delete the bundle script tag.
   ============================================================ */

"use strict";

const fs = require("fs");
const path = require("path");

const goalsDir = process.argv[2] || "goals";
const manifestPath = path.join(goalsDir, "index.json");
const outPath = path.join(goalsDir, "bundle.js");

if (!fs.existsSync(manifestPath)) {
  console.error("No manifest at " + manifestPath);
  process.exit(1);
}

const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
const chunks = [];
let total = 0;

manifest.forEach(entry => {
  const file = entry.file || (entry.id + ".json");
  const full = path.join(goalsDir, file);
  if (!fs.existsSync(full)) {
    console.warn("  missing, skipped: " + file);
    return;
  }
  let data;
  try {
    data = JSON.parse(fs.readFileSync(full, "utf8"));
  } catch (e) {
    console.warn("  bad JSON, skipped: " + file + " (" + e.message + ")");
    return;
  }
  const list = {
    id: entry.id,
    name: entry.name || data.name || entry.id,
    goals: data.goals || []
  };
  // Carried through so the Rules button still works off the filesystem —
  // the fetched path keeps these, and the bundle has to match it.
  if (Array.isArray(data.rules) && data.rules.length) list.rules = data.rules;
  if (Array.isArray(data.tips) && data.tips.length) list.tips = data.tips;
  total += list.goals.length;
  chunks.push("HexBingoGoals(" + JSON.stringify(list) + ");");
  console.log("  " + list.name + " — " + list.goals.length + " goals");
});

fs.writeFileSync(outPath,
  "/* Generated by tools/build-bundle.js — do not edit.\n" +
  "   Offline fallback for opening index.html over file://.\n" +
  "   The JSON files in this folder are the source of truth. */\n" +
  chunks.join("\n") + "\n");

console.log("\nWrote " + outPath + " — " + chunks.length + " lists, " + total + " goals.");
